pub fn vanilla_mob_effect_type(id: i32) -> Option<&'static MobEffectTypeCatalogEntry> {
    VANILLA_MOB_EFFECT_TYPES.get(usize::try_from(id).ok()?)
}

pub fn vanilla_mob_effect_type_for_resource_id(
    resource_id: &str,
) -> Option<&'static MobEffectTypeCatalogEntry> {
    VANILLA_MOB_EFFECT_TYPES
        .iter()
        .find(|entry| entry.resource_id == resource_id)
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn mob_effect_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_MOB_EFFECT_TYPES.len(), 40);
        let mut constants = HashSet::new();
        let mut resources = HashSet::new();
        for (id, entry) in VANILLA_MOB_EFFECT_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(constants.insert(entry.constant_name));
            assert!(resources.insert(entry.resource_id));
        }
        assert_eq!(
            VANILLA_MOB_EFFECT_TYPES
                .iter()
                .filter(|entry| entry.category == MobEffectCategory::Beneficial)
                .count(),
            20
        );
        assert_eq!(
            VANILLA_MOB_EFFECT_TYPES
                .iter()
                .filter(|entry| entry.category == MobEffectCategory::Harmful)
                .count(),
            16
        );
        assert_eq!(
            VANILLA_MOB_EFFECT_TYPES
                .iter()
                .filter(|entry| entry.category == MobEffectCategory::Neutral)
                .count(),
            4
        );
        assert_eq!(
            VANILLA_MOB_EFFECT_TYPES
                .iter()
                .map(|entry| entry.attribute_modifiers.len())
                .sum::<usize>(),
            12
        );
        assert_eq!(
            vanilla_mob_effect_type(VANILLA_MOB_EFFECT_SPEED_ID)
                .unwrap()
                .attribute_modifiers[0]
                .modifier_id,
            "minecraft:effect.speed"
        );
    }

    #[test]
    fn mob_effect_catalog_preserves_vanilla_order_and_metadata() {
        assert_eq!(VANILLA_MOB_EFFECT_SPEED_ID, 0);
        assert_eq!(VANILLA_MOB_EFFECT_NIGHT_VISION_ID, 15);
        assert_eq!(VANILLA_MOB_EFFECT_BREATH_OF_THE_NAUTILUS_ID, 39);
        assert_eq!(
            vanilla_mob_effect_type(18).unwrap().category,
            MobEffectCategory::Harmful
        );
        assert_eq!(
            vanilla_mob_effect_type(30).unwrap().category,
            MobEffectCategory::Neutral
        );
        assert_eq!(
            vanilla_mob_effect_type_for_resource_id("minecraft:conduit_power")
                .unwrap()
                .id,
            28
        );
        assert_eq!(vanilla_mob_effect_type(-1), None);
        assert_eq!(vanilla_mob_effect_type(40), None);
    }

    #[test]
    fn beacon_effect_tiers_preserve_vanilla_membership_and_order() {
        assert_eq!(VANILLA_BEACON_EFFECT_TIERS.len(), 4);
        assert_eq!(
            VANILLA_BEACON_EFFECT_TIERS[0],
            &[VANILLA_MOB_EFFECT_SPEED_ID, VANILLA_MOB_EFFECT_HASTE_ID]
        );
        assert_eq!(
            VANILLA_BEACON_EFFECT_TIERS[1],
            &[
                VANILLA_MOB_EFFECT_RESISTANCE_ID,
                VANILLA_MOB_EFFECT_JUMP_BOOST_ID
            ]
        );
        assert_eq!(
            VANILLA_BEACON_EFFECT_TIERS[2],
            &[VANILLA_MOB_EFFECT_STRENGTH_ID]
        );
        assert_eq!(
            VANILLA_BEACON_EFFECT_TIERS[3],
            &[VANILLA_MOB_EFFECT_REGENERATION_ID]
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_mob_effect_catalog_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/mob_effect_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("SPEED_ATTRIBUTE_MODIFIERS")
                    || production.contains("fn attribute_modifier(\n")
                    || production.contains("const BEACON_PRIMARY_EFFECT_ROWS")
                    || production.contains("const BEACON_SECONDARY_EFFECTS")
                    || production.contains("fn vanilla_mob_effect_resource_id(")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel mob-effect catalog owners or lookup bridges: {violations:?}"
        );
    }
}
